package app.tvframe

import android.content.Context
import android.graphics.Typeface
import android.os.Handler
import android.os.HandlerThread
import android.provider.FontRequest
import android.provider.FontsContract
import android.util.Base64
import android.util.Log

/**
 * Google Sans and Google Sans Text, loaded at runtime from Play services fonts, the same way the stock
 * launcher and ambient mode get them (the system partition only has Roboto). Until they arrive, or if
 * the provider refuses, every face falls back to Roboto.
 */
object Fonts {
    // GMS font provider certificates, as shipped in com.google.android.apps.tv.dreamx (prod and dev keys).
    private const val PROD = ""
    private const val DEV = ""

    enum class Face(val query: String, val fallbackFamily: String) {
        SANS("Google Sans", "sans-serif"),
        SANS_MEDIUM("Google Sans:500", "sans-serif-medium"),
        TEXT("Google Sans Text", "sans-serif"),
        TEXT_MEDIUM("Google Sans Text:500", "sans-serif-medium"),
    }

    private val faces = HashMap<Face, Typeface>()
    private val listeners = ArrayList<() -> Unit>()
    @Volatile var loaded = 0; private set
    private var started = false

    fun get(f: Face): Typeface = synchronized(faces) { faces[f] } ?: Typeface.create(f.fallbackFamily, Typeface.NORMAL)

    /** Call once per process. [onChange] listeners run on the main thread when a face arrives. */
    fun load(ctx: Context) {
        if (started) return
        started = true
        val certs = listOf(listOf(Base64.decode(PROD, 0)), listOf(Base64.decode(DEV, 0)))
        val th = HandlerThread("fonts").apply { start() }
        val h = Handler(th.looper)
        val main = Handler(ctx.mainLooper)
        for (f in Face.values()) {
            val req = FontRequest("com.google.android.gms.fonts", "com.google.android.gms", f.query, certs)
            FontsContract.requestFonts(ctx, req, h, null, object : FontsContract.FontRequestCallback() {
                override fun onTypefaceRetrieved(typeface: Typeface) {
                    synchronized(faces) { faces[f] = typeface }
                    loaded++
                    Log.i(TAG, "font ${f.query}: from Play services")
                    main.post { listeners.toList().forEach { it() } }
                }
                override fun onTypefaceRequestFailed(reason: Int) {
                    Log.w(TAG, "font ${f.query}: provider failed ($reason), using ${f.fallbackFamily}")
                }
            })
        }
    }

    fun onChange(l: () -> Unit) { listeners += l }
    fun removeListener(l: () -> Unit) { listeners -= l }
}
